import{_ as d,C as a,o,c as n,E as r,a2 as i}from"./chunks/framework.Cm6XCzck.js";const C=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.5","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.5","type":"implementation-case","domain":"TMPA","version":"I0.5","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.5.md","filePath":"zh/publications/implementation-case-i0.5.md","lastUpdated":1785916356000}'),c={name:"zh/publications/implementation-case-i0.5.md"};function s(l,e,p,h,u,P){const t=a("ArticleCover");return o(),n("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"S0.4 工程基线，以及 WP-13 多 Agent 证据门控与事实复核案例。",version:"I0.5",status:"S0.4 工程证据草稿",languageHref:"/en/publications/implementation-case-i0.5",languageLabel:"English"}),e[0]||(e[0]=i(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="s0-4-reference-reader、fcop、codeflowmu-与-wp-13-多-agent-事实复核" tabindex="-1">S0.4 Reference Reader、FCoP、CodeFlowMu 与 WP-13 多 Agent 事实复核 <a class="header-anchor" href="#s0-4-reference-reader、fcop、codeflowmu-与-wp-13-多-agent-事实复核" aria-label="Permalink to &quot;S0.4 Reference Reader、FCoP、CodeFlowMu 与 WP-13 多 Agent 事实复核&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> Draft I0.5<br><strong>状态：</strong> 作者生成的实施与案例报告<br><strong>规范目标：</strong> TMPA Core S0.4<br><strong>历史证据基线：</strong> I0.3 / S0.3 语料库<br><strong>报告与执行日期：</strong> 2026-08-03；WP-13 案例观察日期 2026-08-05<br><strong>一致性语料库：</strong> <code>tmpa-s0.4-fcop-codeflowmu-20260803</code><br><strong>权威边界：</strong> 本报告只提供工程证据，不具有规范性；TMPA Core 要求仅由 GitHub Core Specification 定义。</p></blockquote><h1 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h1><p>本报告把 Implementation Case 从一个未进入 GitHub 的 S0.3 时代本地归档，推进为公开、可执行的 S0.4 语料库。I0.5 保留 I0.4 的 Reference Reader、C01–C14 Fixture、Manifest、结果 Envelope、产品证据断言与单命令 Runner，并新增 WP-13 现场案例：当子执行产生带有“完成”意味但缺乏退出状态、测试、Commit 与正式 REPORT 的声明时，PM 根据持久事实不予放行；DEV 恢复后在原任务补齐交付，再由角色分离的 QA 验证。</p><p>FCoP 协议定义项目可见的协调 Profile：路由文本工件、生命周期路径、原子 Rename、只增迁移证据、角色绑定、复核、ISSUE、告警和检查报告都保存在临时模型 Session 之外；其参考实现为这些规则提供有界的可执行证据。CodeFlowMu 作为下游应用采用该协议，用于持久工作身份、任务—报告流、复核门禁、依赖等待、恢复和归档历史。小典 AI 提供来自受治理 NL2SQL Pipeline 的前规范现场证据，包括被保留的通过路径和拒绝路径。</p><p>S0.4 Reference Reader 针对作者生成的合成 Fixture 套件得到 <strong>14 PASS</strong>。单独求值的 FCoP–CodeFlowMu 产品基线仍为 <strong>1 PASS、9 PARTIAL、4 NOT RUN、0 FAIL</strong>，聚合裁决为 <code>PARTIAL</code>。WP-13 增强了 C04、C06、C07 与 C13 相关行为的作者生成 <code>demonstrated</code> 证据，但没有执行新的 S0.4 产品 Reader 标准，因此不改写上述裁决，也不建立独立验证。</p><h1 id="_1-范围与证据边界" tabindex="-1">1. 范围与证据边界 <a class="header-anchor" href="#_1-范围与证据边界" aria-label="Permalink to &quot;1. 范围与证据边界&quot;">​</a></h1><p>本报告回答：S0.4 Reference Reader 实现了什么；锁定产品证据实际演示了什么；哪些 S0.4 产品要求仍未执行。本报告只提供工程证据且不具有规范性，其裁决保留在历史 S0.4 目标下；当前要求与规范测试名称由 <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a> 定义，I0.5 不声明 S0.5 一致性。理论由 <a href="/joinwell52/zh/publications/tmpa-architecture-paper-a0.5">Architecture Paper A0.5</a> 解释。</p><p>证据仍分为 <code>specified</code>、<code>implemented</code>、<code>demonstrated</code> 与 <code>independently adopted</code>。Reference Reader 已实现并由作者演示；产品基线包含混合的 implemented/demonstrated 证据，聚合仍为 <code>PARTIAL</code>。Fixture 成功不得转换为 FCoP 或 CodeFlowMu 产品一致性，也不建立独立采用或独立验证。</p><h1 id="_2-工程谱系与组件边界" tabindex="-1">2. 工程谱系与组件边界 <a class="header-anchor" href="#_2-工程谱系与组件边界" aria-label="Permalink to &quot;2. 工程谱系与组件边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前概念分层</span></span>
<span class="line"><span>TMPA 架构 → 可复用 FCoP 协议 Profile → CodeFlowMu 与其他下游应用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>历史谱系</span></span>
<span class="line"><span>小典 AI 实践 → 原始 TMPA → FCoP 抽取与成熟</span></span>
<span class="line"><span>              → CodeFlowMu 应用 → 当前 TMPA 形式化</span></span></code></pre></div><p>FCoP 定义覆盖 TMPA 部分文件型语义的协议 Profile；<code>fcop</code> 与 <code>fcop-mcp</code> Package 是其参考实现，CodeFlowMu 是把该协议作为协调与治理基础设施采用的下游应用。FCoP 不穷尽 TMPA；CodeFlowMu 不定义 FCoP；小典 AI 是谱系和现场证据，不是产品级 TMPA Reader。</p><p>术语遵循 Core Specification 第 2 节：<strong>治理对象</strong>是语义单元，<strong>来源工件</strong>是物理观测，<strong>治理 Reader</strong>是确定性重建阶段，<code>valid</code> / <code>invalid</code> / <code>undetermined</code> 是仅有的三个治理语义判断。本报告不引入替代含义。</p><h1 id="_3-fcop-协议与参考实现证据" tabindex="-1">3. FCoP 协议与参考实现证据 <a class="header-anchor" href="#_3-fcop-协议与参考实现证据" aria-label="Permalink to &quot;3. FCoP 协议与参考实现证据&quot;">​</a></h1><h2 id="_3-1-持久文本消息与状态表面" tabindex="-1">3.1 持久文本消息与状态表面 <a class="header-anchor" href="#_3-1-持久文本消息与状态表面" aria-label="Permalink to &quot;3.1 持久文本消息与状态表面&quot;">​</a></h2><p>FCoP 把项目文件系统作为持久文本消息与状态表面：<strong>文件承载协议，路径表达状态，事件回放迁移。</strong> <code>TASK-*</code> 工件作为稳定工作锚点；报告、复核、ISSUE、告警与决策保持独立；文件名携带路由；生命周期目录暴露状态；原子 Rename 执行迁移；迁移证据说明状态如何到达；工件在 Session 结束后仍可检查。</p><h2 id="_3-2-agent-可见角色绑定" tabindex="-1">3.2 Agent 可见角色绑定 <a class="header-anchor" href="#_3-2-agent-可见角色绑定" aria-label="Permalink to &quot;3.2 Agent 可见角色绑定&quot;">​</a></h2><p>受治理参与从 Agent 可见的显式角色绑定开始。绑定规定角色、协作上下文、任务范围、允许/禁止动作以及独立复核或升级角色。它是运行协议身份，不是密码学或法律身份。</p><h2 id="_3-3-生命周期" tabindex="-1">3.3 生命周期 <a class="header-anchor" href="#_3-3-生命周期" aria-label="Permalink to &quot;3.3 生命周期&quot;">​</a></h2><p>参考生命周期为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox → active → review → done → archive → history</span></span>
<span class="line"><span>           ↑        |</span></span>
<span class="line"><span>           └─ reject┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>动作</th><th>来源状态</th><th>目标状态</th><th>典型权限</th></tr></thead><tbody><tr><td><code>create_task</code></td><td>—</td><td><code>inbox</code></td><td>任务创建者</td></tr><tr><td><code>claim_task</code></td><td><code>inbox</code></td><td><code>active</code></td><td>被分配的执行者</td></tr><tr><td><code>submit_task</code></td><td><code>active</code></td><td><code>review</code></td><td>责任执行者</td></tr><tr><td><code>approve_task</code></td><td><code>review</code></td><td><code>done</code></td><td>复核者或批准者</td></tr><tr><td><code>reject_task</code></td><td><code>review</code></td><td><code>active</code></td><td>复核者</td></tr><tr><td><code>finish_task</code></td><td><code>active</code></td><td><code>done</code></td><td>Profile 授权角色</td></tr><tr><td><code>archive_task</code></td><td><code>done</code></td><td><code>archive</code></td><td>归档权限</td></tr><tr><td><code>archive_to_history</code></td><td><code>archive</code></td><td><code>history/...</code></td><td>归档权限</td></tr></tbody></table><p>路径表示当前 Profile 状态，迁移证据记录过程历史。路径与证据不一致时必须形成 ISSUE，而不是静默修复。</p><h2 id="_3-4-路由、原子发布与恢复" tabindex="-1">3.4 路由、原子发布与恢复 <a class="header-anchor" href="#_3-4-路由、原子发布与恢复" aria-label="Permalink to &quot;3.4 路由、原子发布与恢复&quot;">​</a></h2><p>参考文件名为 <code>{TYPE}-{YYYYMMDD}-{NNN}-{SENDER}-to-{RECIPIENT}(-slug).md</code>。文件名是传输封装；正文与 Schema 承载完整含义。在支持的平台上，原子发布通过先写临时文件再 Rename 实现。恢复从持久工件重建任务身份、当前生命周期、责任、关联证据、未解决依赖与问题，不依赖隐藏 Session 上下文。</p><h1 id="_4-codeflowmu-持久工作环境" tabindex="-1">4. CodeFlowMu 持久工作环境 <a class="header-anchor" href="#_4-codeflowmu-持久工作环境" aria-label="Permalink to &quot;4. CodeFlowMu 持久工作环境&quot;">​</a></h1><p>CodeFlowMu 研究跨 Session 持续存在的 AI 工作角色。模型和 Session 可以变化，但工作身份通过角色绑定、任务/Thread ID、报告和复核、批准/拒绝记录、生命周期迁移、未解决 ISSUE/依赖、恢复和归档证据继续存在。</p><p>这里的“数字员工”只表示能够接受委托工作、使用工具并跨 Session 提交证据的工程身份，不表示法律雇佣、人格、意识、人类意图，也不表示替代承担责任的人类或组织。</p><p>一项已观察 Session 展示了协议初始化与参与者身份的区别：FCoP 已初始化，但 Session 尚未分配角色；Agent 在制定开发计划前请求显式角色绑定，在获得 PM/共同复核者绑定后才确认角色并创建受治理规划工作。该观察只建立运行角色可见性，不建立密码学认证。</p><p>观察与测试路径包括 ADMIN/PM 委托、执行者 Claim 与执行、独立报告提交、QA/治理复核、批准/拒绝/等待人工状态、依赖等待与释放、ISSUE 创建、重启恢复和归档历史。当前限制是这些局部发现尚未被统一规范化为 TMPA 证据图与问题集合，因此 C13 仍为 PARTIAL。</p><p>当必需证据缺失、过期或不完整时，实现可以阻止 Release。CodeFlowMu 已保存足以证明部分重启与恢复行为的 Session、任务、报告、生命周期和 Ledger 证据，但尚无单一产品 Reader 把责任、生命周期、未解决依赖、冲突与问题重建为一个规范输出。</p><h1 id="_5-小典-ai-nl2sql-案例" tabindex="-1">5. 小典 AI NL2SQL 案例 <a class="header-anchor" href="#_5-小典-ai-nl2sql-案例" aria-label="Permalink to &quot;5. 小典 AI NL2SQL 案例&quot;">​</a></h1><p>公开演示位于 <code>https://demo.chedian.cc/</code>。产生数据的私有开发系统与公开仓库不被声称为同一个可直接复现构建。2026-07-29 快照显示 330 Profile、16,129 Event、924 Message、1,220 Index/Export、44 Knowledge 和 352 Audit 记录；这些是单次系统状态，不是性能基准。</p><p>NL2SQL 链覆盖授权、意图规范化、Schema/DDL 上下文、SQL 生成、只读验证、写入阻断、表白名单、租户隔离、字段/Join/枚举验证和结果合理性检查。一个车辆违法查询在 26,344 ms 后通过；一个车辆费用汇总查询在 131,994 ms 后被拒绝。价值在于保留通过与拒绝路径的分歧，而不是计算代表性通过率。</p><p>被拒绝链保留请求身份、验证阶段、明确结果、耗时、跨 Session 证据以及治理证据与生成 SQL 的分离。它演示真实应用能够保存治理相关记录、重建多阶段链、把拒绝保留为一等结果并展示策略门禁；它不证明完整 TMPA Core 一致性、代表性 SME 性能、独立采用、密码学不可抵赖性或每条记录的事实正确性。</p><h1 id="_6-公开-s0-4-c01–c14-语料库" tabindex="-1">6. 公开 S0.4 C01–C14 语料库 <a class="header-anchor" href="#_6-公开-s0-4-c01–c14-语料库" aria-label="Permalink to &quot;6. 公开 S0.4 C01–C14 语料库&quot;">​</a></h1><p>I0.3 曾描述本地 <code>tmpa-conformance.zip</code>，但该归档、Runner 与 Fixture 并未进入 GitHub 唯一事实源。I0.4 以公开仓库语料库 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a> 取代不可用的交付声明；语料库 ID 为 <code>tmpa-s0.4-fcop-codeflowmu-20260803</code>。</p><p>语料库刻意分成两条证据轨道：</p><ol><li><strong>S0.4 Reference Reader 轨道。</strong> 只读实现消费合成 Fixture，验证公开 S0.4 Schema 与可执行 Profile，重建规范节点、边、问题、判断和视图，再核验 C01–C14 断言。</li><li><strong>锁定产品基线轨道。</strong> 机器可读断言把可取得的 FCoP、CodeFlowMu 与小典证据按更严格的 S0.4 标准重新裁决。Fixture PASS 绝不提升为产品 PASS。</li></ol><p>仓库命令为 <code>npm run tmpa:s0.4:conformance</code>。它在不修改产品仓库的前提下重新生成标准记录、Reference 与 Product 结果、执行日志、汇总和 SHA-256 文件 Manifest。Runner 对 S0.4 对象与 Reader Result Envelope 进行严格 JSON Schema 验证，并在求值前验证可执行的 Lifecycle/Type/Role/Relation Profile。</p><p>状态语义固定为：PASS 表示该轨道全部强制断言都已执行并匹配；PARTIAL 表示存在真实产品证据，但至少缺少一项 S0.4 必需观察或输出；NOT RUN 表示所需产品执行路径不可用；FAIL 表示已执行的强制断言不匹配。只有产品 C01–C14 全部 PASS 时，产品聚合结果才是 PASS。</p><p>FCoP <code>3.2.4</code> Commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code> 已直接取回，并在 Python 3.12.13 上重跑：<strong>1,137 项通过、2 项跳过、0 项失败</strong>。CodeFlowMu <code>V1.2.3</code> 锁定 Commit <code>8f342d028eb66e77d135bea58fdbc7f2d0627e3b</code> 无法从公开 <code>CodeFlowMu-open</code> 历史取回，因此 I0.4 将新的 CodeFlowMu 执行记录为 NOT RUN，只把 I0.3 保存的断言用于有边界的重新裁决。</p><table tabindex="0"><thead><tr><th>证据轨道</th><th style="text-align:right;">PASS</th><th style="text-align:right;">PARTIAL</th><th style="text-align:right;">NOT RUN</th><th style="text-align:right;">FAIL</th><th>聚合</th><th>声明级别</th></tr></thead><tbody><tr><td>S0.4 Reference Reader Fixture</td><td style="text-align:right;">14</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>PASS</td><td>Implemented 且由作者 Demonstrated</td></tr><tr><td>FCoP–CodeFlowMu 产品基线</td><td style="text-align:right;">1</td><td style="text-align:right;">9</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td>PARTIAL</td><td>混合产品证据</td></tr></tbody></table><p>Reference Reader 结果表明已发布的解释可以执行。它<strong>不</strong>建立 FCoP、CodeFlowMu 或小典对 S0.4 的完整一致性，也不建立独立采用。</p><h1 id="_7-标准级结果" tabindex="-1">7. 标准级结果 <a class="header-anchor" href="#_7-标准级结果" aria-label="Permalink to &quot;7. 标准级结果&quot;">​</a></h1><p>下表中的测试名称与含义直接引用 Core Specification 第 10.2 节；本报告只记录产品证据与剩余缺口。</p><table tabindex="0"><thead><tr><th>ID</th><th>规范测试名称</th><th>裁决</th><th>产品证据与剩余缺口</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证</td><td>PARTIAL</td><td>FCoP 与 CodeFlowMu 已有 Schema 和验证路径，但完整 TMPA 规范对象覆盖及全部负向格式案例尚未由一个 Core Validator 暴露。</td></tr><tr><td>C02</td><td>主载体与单写者不可变性</td><td>PARTIAL</td><td>独立工件与更正证据已存在；更严格的不可变对象与一任务一主载体观察仍不完整。</td></tr><tr><td>C03</td><td>重复对象 ID</td><td>PARTIAL</td><td>局部重复与冲突机制已存在，但相同 ID、不同内容的规范隔离视图尚未端到端暴露。</td></tr><tr><td>C04</td><td>串行流连续性与异步推进</td><td>PARTIAL</td><td>局部排序、依赖等待与异步推进已实现；尚未输出统一规范偏序图与流缺口问题集合。</td></tr><tr><td>C05</td><td>角色权限</td><td>PARTIAL</td><td>角色、Capability 与操作门禁已存在；全部失败尚未规范化为统一权威 TMPA 问题模型。</td></tr><tr><td>C06</td><td>生命周期合法性</td><td>PARTIAL</td><td>直接生命周期测试覆盖非法与未授权迁移，但产品证据尚未同时输出 S0.4 要求的 <code>ILLEGAL_TRANSITION</code>/<code>invalid</code> 与 <code>LIFECYCLE_UNDETERMINED</code>/<code>undetermined</code> 两类规范结果。</td></tr><tr><td>C07</td><td>职责分离</td><td>PARTIAL</td><td>独立报告、复核与 Review Gate 已存在，但身份级分离和例外对象处理尚未完整演示。</td></tr><tr><td>C08</td><td>完整性篡改</td><td>NOT RUN</td><td>Fixture Oracle 已存在；产品级被覆盖内容 Digest 验证与规范篡改 Reader 未执行。</td></tr><tr><td>C09</td><td>缺失引用</td><td>PARTIAL</td><td>缺失依赖可以阻塞工作，但完整 <code>undetermined</code>/partial 图传播与规范问题输出仍不完整。</td></tr><tr><td>C10</td><td>禁止环</td><td>NOT RUN</td><td>禁止环 Fixture 已存在；能够只隔离受影响子图的产品图 Reader 不可用。</td></tr><tr><td>C11</td><td>聚合与重建确定性</td><td>NOT RUN</td><td>Fixture Oracle 在 24 种排列下产生字节等价输出；产品级规范图与问题序列化器不可用。</td></tr><tr><td>C12</td><td>冲突保留</td><td>NOT RUN</td><td>冲突保留 Fixture 已存在；产品级确定性 disputed/<code>undetermined</code> 视图与授权解决路径未作为一项标准执行。</td></tr><tr><td>C13</td><td>恢复</td><td>PARTIAL</td><td>重启与恢复机制已存在，但没有统一的全新 Reader 重建全部责任、生命周期、依赖与问题状态。</td></tr><tr><td>C14</td><td>终态历史保留</td><td>PASS</td><td>直接 Archive/History 测试保留终态、迁移、先前报告、复核与任务证据。</td></tr></tbody></table><p>独立的 S0.4 Reference Reader 轨道通过全部 14 项合成 Fixture 断言。这些结果验证可执行解释与确定性 Runner，不验证表中产品。</p><h1 id="_8-产品投影缺口" tabindex="-1">8. 产品投影缺口 <a class="header-anchor" href="#_8-产品投影缺口" aria-label="Permalink to &quot;8. 产品投影缺口&quot;">​</a></h1><p>Publication 仓库现已包含通用 S0.4 只读 Reference Reader。主要产品缺口因此更具体：两个锁定产品都没有受维护的投影适配器，把各自原生工件转换为该 Reader 消费的 S0.4 来源对象表面。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>来源工件</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>保留来源追踪的来源候选</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>规范候选集合</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>偏序流程与责任图</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>规范问题集合</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>valid / invalid / undetermined 判断</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>authoritative / quarantined / partial / disputed / pending_human 视图</span></span></code></pre></div><p>FCoP 与 CodeFlowMu 已具备独立工件、原子发布、角色检查、生命周期门禁、依赖阻塞、Archive 保留和重启恢复等写入侧与局部控制机制。产品专用投影将直接改善 C03、C05、C09、C13，为 C04/C07 提供基础设施，并建立 C10–C12 所需的产品执行路径。C01 仍有 Schema 覆盖缺口；C02 仍有更严格不可变性缺口；C06 缺少完整的规范三值输出对；C08 需要被覆盖内容的 Digest 证据。CodeFlowMu 还需要可公开取回的锁定源码或复现包。</p><h1 id="_9-worked-flow-中的三值治理" tabindex="-1">9. Worked Flow 中的三值治理 <a class="header-anchor" href="#_9-worked-flow-中的三值治理" aria-label="Permalink to &quot;9. Worked Flow 中的三值治理&quot;">​</a></h1><p>TMPA 区分语义判断与视图分类：</p><table tabindex="0"><thead><tr><th>语义判断</th><th>视图分类</th><th>含义</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>必需证据与规则建立结论</td></tr><tr><td><code>invalid</code></td><td>quarantined 或 rejected</td><td>确定性违规排除受影响证据或动作</td></tr><tr><td><code>undetermined</code></td><td>partial</td><td>必需证据缺失或不完整</td></tr><tr><td><code>undetermined</code></td><td>disputed</td><td>有效证据冲突且没有授权解决</td></tr><tr><td><code>undetermined</code></td><td>pending_human</td><td>适用 Profile 要求人工决定</td></tr></tbody></table><p>代表性复核流程为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK → REPORT → QA REVIEW(needs_human)</span></span>
<span class="line"><span>                       ↓</span></span>
<span class="line"><span>          judgment: undetermined</span></span>
<span class="line"><span>          view: pending_human</span></span>
<span class="line"><span>          lifecycle: blocked_pending_resolution</span></span>
<span class="line"><span>                       ↓</span></span>
<span class="line"><span>              ADMIN DECISION</span></span>
<span class="line"><span>             ↙              ↘</span></span>
<span class="line"><span>        approve             reject</span></span>
<span class="line"><span>          ↓                   ↓</span></span>
<span class="line"><span>        valid              invalid</span></span></code></pre></div><p><code>needs_human</code> 状态保持在图中并可查询，不得被提前表示为 done、approved、failed 或 rejected。依赖该未解决复核的下游对象保持 <code>undetermined</code>，直至增加授权决定对象。</p><p>S0.4 Reference Reader 已在合成 Fixture 上演示该三值流程。当前 CodeFlowMu 已有等待人工和注意状态，但产品级 Core 判断/视图规范化仍是实现目标，不是已经完整演示的产品声明。</p><h1 id="_10-wp-13-工具结果不确定时的多-agent-证据门控" tabindex="-1">10. WP-13：工具结果不确定时的多 Agent 证据门控 <a class="header-anchor" href="#_10-wp-13-工具结果不确定时的多-agent-证据门控" aria-label="Permalink to &quot;10. WP-13：工具结果不确定时的多 Agent 证据门控&quot;">​</a></h1><h2 id="_10-1-研究问题与观察单元" tabindex="-1">10.1 研究问题与观察单元 <a class="header-anchor" href="#_10-1-研究问题与观察单元" aria-label="Permalink to &quot;10.1 研究问题与观察单元&quot;">​</a></h2><p>WP-13 记录了一个对 TMPA 三值治理具有直接意义的现场事件：子执行工具结束后给出带有“完成”意味的总结，但同一原始事件也明确保留 <code>no exit status</code>、测试未确认、Commit SHA 不可得等限制。研究问题不是“模型为什么产生错误句子”，而是：</p><blockquote><p>在 Agent 声明与持久工作事实不闭合时，多 Agent 治理系统能否阻止未经证实的声明进入权威交付链？</p></blockquote><p>观察窗口为 2026-08-05 12:59—13:11（Asia/Shanghai）。公开证据集保留两份 TASK、DEV/QA REPORT、子执行原始 JSONL、300 行 Runtime 事件节选、Git 补丁与 Manifest、5 份 QA JSON、会话摘录与边界说明。该证据集是作者生成的工程证据，不是第三方审计。</p><h2 id="_10-2-从未确认声明到可复核交付" tabindex="-1">10.2 从未确认声明到可复核交付 <a class="header-anchor" href="#_10-2-从未确认声明到可复核交付" aria-label="Permalink to &quot;10.2 从未确认声明到可复核交付&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>可观察事实</th><th>治理结果</th></tr></thead><tbody><tr><td>DEV 子执行</td><td>工具事件结束，但内部命令缺少可确认退出状态；测试与 SHA 未确认</td><td>工具调用结束不等于业务完成</td></tr><tr><td>PM 事实复核</td><td>磁盘上无正式 DEV REPORT，指定测试文件未落盘，Git HEAD 仍为前一 WP</td><td>不放行，不派 QA，不复制新任务</td></tr><tr><td>同任务恢复</td><td>工具通道恢复后，DEV 补齐实现、测试、Commit <code>609571dd…</code> 与 <code>REPORT-037</code></td><td>交付开始具备可核查外部事实</td></tr><tr><td>角色分离 QA</td><td><code>QA-01</code> 针对 <code>DEV-01</code> 交付重跑 27 项测试、typecheck 与 diff check</td><td>27/27 PASS；typecheck 0；diff check 0</td></tr></tbody></table><p>这条链不证明模型不再出错。它演示的是<strong>治理层容错</strong>：自然语言声明只是候选证据；在 TASK、REPORT、Git 与测试结果不闭合前，该声明不能改变权威交付状态。</p><h2 id="_10-3-tmpa-三值解释" tabindex="-1">10.3 TMPA 三值解释 <a class="header-anchor" href="#_10-3-tmpa-三值解释" aria-label="Permalink to &quot;10.3 TMPA 三值解释&quot;">​</a></h2><p>对观察时刻 <code>τ₀</code> 进行 S0.4 后验分析时，“WP-13 已完成”不应被解释为 <code>valid</code>，因为必需证据尚不存在或无法确认；也不应直接解释为 <code>invalid</code>，因为当时尚未证明实现本身违反验收规则。适当的语义是 <code>undetermined</code>，运行视图为 <code>partial</code>；PM 等待证据而不放行。</p><p>这是对现场证据的 S0.4 分析性投影，不是 CodeFlowMu 当时已输出规范 Reader Envelope 的声明。原生系统没有发布 <code>LIFECYCLE_UNDETERMINED</code>、规范问题集与绑定 Profile 的三值结果，所以该案例不使 C06 升级为 PASS。</p><h2 id="_10-4-从-tmpa-到-fcop-与-codeflowmu" tabindex="-1">10.4 从 TMPA 到 FCoP 与 CodeFlowMu <a class="header-anchor" href="#_10-4-从-tmpa-到-fcop-与-codeflowmu" aria-label="Permalink to &quot;10.4 从 TMPA 到 FCoP 与 CodeFlowMu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>本案例中的实现</th></tr></thead><tbody><tr><td>TMPA</td><td>区分声明、证据与权威判断；必需证据不完整时保持 <code>undetermined</code></td></tr><tr><td>FCoP</td><td>TASK 作为稳定主载体，REPORT 独立发布，<code>references</code>/<code>depends_on</code> 保留任务与报告关系</td></tr><tr><td>CodeFlowMu</td><td>Runtime 记录工具事件与任务状态，PM 执行业务事实复核，DEV 恢复原任务，QA 按分离角色验证</td></tr></tbody></table><table tabindex="0"><thead><tr><th>证据维度</th><th>Specified</th><th>Implemented</th><th>Demonstrated</th><th>Independently Adopted</th></tr></thead><tbody><tr><td>证据不完整时的三值判断</td><td>S0.4</td><td>产品有局部等待/复核控制</td><td>WP-13 后验分析</td><td>否</td></tr><tr><td>TASK/REPORT 持久事实链</td><td>FCoP Profile</td><td>是</td><td>是</td><td>否</td></tr><tr><td>DEV–PM–QA 职责分离</td><td>S0.4/FCoP Profile</td><td>是</td><td><code>DEV-01</code>/PM/<code>QA-01</code></td><td>否</td></tr><tr><td>同任务恢复与证据补齐</td><td>S0.4 恢复目标</td><td>是</td><td>是</td><td>否</td></tr><tr><td>WP-13 产品投影适配器与规范 Reader 输出</td><td>S0.4</td><td>否</td><td>否</td><td>否</td></tr></tbody></table><h2 id="_10-5-对-c01–c14-的证据贡献" tabindex="-1">10.5 对 C01–C14 的证据贡献 <a class="header-anchor" href="#_10-5-对-c01–c14-的证据贡献" aria-label="Permalink to &quot;10.5 对 C01–C14 的证据贡献&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标准</th><th>WP-13 增量证据</th><th>I0.5 裁决影响</th></tr></thead><tbody><tr><td>C04</td><td>TASK-019 → REPORT-037 → TASK-020 → REPORT-038 以及 Runtime 事件形成可追踪串行链</td><td>增强 demonstrated 证据；仍为 PARTIAL</td></tr><tr><td>C06</td><td>必需证据不足时不改变权威交付状态</td><td>没有规范问题码与 Reader 结果；仍为 PARTIAL</td></tr><tr><td>C07</td><td>DEV 交付、PM 复核、QA 验证不由同一工作角色完成</td><td>角色分离得到现场演示；身份认证与例外对象仍缺，裁决为 PARTIAL</td></tr><tr><td>C09</td><td>中间时刻缺失必需 REPORT、Commit 与测试证据</td><td>支持证据不完整分析，但未输出规范 <code>MISSING_REFERENCE</code>；仍为 PARTIAL</td></tr><tr><td>C13</td><td>工具恢复后续办原 TASK，补齐 Git、REPORT 与 QA 证据</td><td>增强恢复行为证据；没有全新 Reader 等价重建，仍为 PARTIAL</td></tr><tr><td>C08/C11/C12</td><td>包含未签名校验和、原始/可读投影对照与相互冲突声明的保留</td><td>只是支持材料；不替代产品标准执行，仍为 NOT RUN</td></tr></tbody></table><p>其余标准没有由该案例增加可裁决证据。因此，I0.5 保留 I0.4 的产品聚合结果，不对过往未执行项进行重标记。</p><h2 id="_10-6-证据边界" tabindex="-1">10.6 证据边界 <a class="header-anchor" href="#_10-6-证据边界" aria-label="Permalink to &quot;10.6 证据边界&quot;">​</a></h2><ul><li>QA 是角色分离验证，不是外部第三方独立验证。</li><li><code>dev-report-037.md</code> 与 <code>qa-report-038.md</code> 保留 <code>runtime_bound: False</code>，不是 Runtime 认证证据。</li><li>证据快照结束时 TASK-019/020 均为 <code>review / pending</code>；该包只证明 DEV 交付与角色分离 QA PASS，不证明快照内已有终态批准或归档。</li><li>同包未签名校验和只验证内部一致性，不证明发布者身份、来源真实性或可信时间戳。</li><li>本案例演示的是未经证实声明的治理遏制，不是对模型所有幻觉的预防或消除。</li></ul><p>完整原始字节包可从 <a href="/joinwell52/evidence/tmpa/i0.5/wp13-multi-agent-fact-check-publication-evidence-v3.zip">WP-13 Publication Evidence V3</a> 下载，外层 SHA-256 为 <code>5b5eda3034c822f13421783244b1d0c76a9fa79950bfad0ce61bb8d2e404131c</code>。</p><h1 id="_11-可复现性与局限" tabindex="-1">11. 可复现性与局限 <a class="header-anchor" href="#_11-可复现性与局限" aria-label="Permalink to &quot;11. 可复现性与局限&quot;">​</a></h1><p>S0.4 语料库现已位于稳定的公开仓库路径，包含单命令执行、Schema、Profile、Fixture、断言、输出、日志与 SHA-256 Manifest。在固定执行时间戳下重复本地运行可产生字节完全一致的工件。本次维护直接取回 FCoP Commit 并成功重跑选定测试套件；CodeFlowMu Commit 无法从公开仓库取得。尚无第三方重跑或独立验证该语料库。</p><p>基线不建立代表性 SME 性能、比较部署成本、广泛容错、独立采用、参与者声明的事实真实性、认证身份、受保护存储或拜占庭韧性。产品与案例证据均由作者产生。公开演示与私有数据生成系统不被声称为同一个可复现公共构建。</p><p>下一阶段需要测量安装依赖与耗时、首个团队启动、CPU/内存/存储增长、延迟与乱序证据下的重建、受控中断与重启、冲突和缺失引用注入、人类可检查性、采用负担，以及相对于聊天、共享目录与简单工作流的基线。</p><h1 id="_12-工程路线" tabindex="-1">12. 工程路线 <a class="header-anchor" href="#_12-工程路线" aria-label="Permalink to &quot;12. 工程路线&quot;">​</a></h1><ol><li>实现受维护的 FCoP 与 CodeFlowMu 投影适配器，同时不改变现有写入行为；</li><li>发布或以其他方式提供可取回的 CodeFlowMu 锁定源码与复现包；</li><li>执行产品级 C08、C10、C11、C12；</li><li>补齐 C01–C07、C09、C13 的规范输出，包括 C06 两个三值分支；</li><li>测量低资源部署、重启与增量重建；</li><li>获得独立重跑并记录全部差异。</li></ol><h1 id="_13-证据声明" tabindex="-1">13. 证据声明 <a class="header-anchor" href="#_13-证据声明" aria-label="Permalink to &quot;13. 证据声明&quot;">​</a></h1><p>本报告提供带版本的工程证据，不提供独立验证。最强结论有明确边界：公开 S0.4 Reference Reader 通过 14/14 项合成标准；锁定产品基线为 C14 PASS、9 项 PARTIAL、4 项 NOT RUN，未观察到 FAIL。零 FAIL 不等于完整一致性，因为 4 项产品标准未执行，9 项仍不完整。更强声明需要产品投影、CodeFlowMu 可复现性、更广泛实验与独立复现。</p><h1 id="_14-工程结论" tabindex="-1">14. 工程结论 <a class="header-anchor" href="#_14-工程结论" aria-label="Permalink to &quot;14. 工程结论&quot;">​</a></h1><p>公开 S0.4 语料库把宽泛工程历史转化为仓库内可测试基线。Reference Reader 通过全部 14 项合成标准；对锁定产品而言，仅 C14 PASS，9 项具有部分证据，4 项未在产品 Reader 层运行。该结果强于无版本演示，但仍弱于完整或独立一致性。</p><p>产品已经包含许多写入侧和局部控制机制。新的通用 Reader 建立确定性读取侧参考，而受维护的产品投影适配器仍是最大的共同缺口。C08、C10、C11、C12 的产品执行、其他 PARTIAL 输出的补齐、量化 SME 部署成本与独立复现，仍是分开的经验要求。</p><h1 id="工件可用性" tabindex="-1">工件可用性 <a class="header-anchor" href="#工件可用性" aria-label="Permalink to &quot;工件可用性&quot;">​</a></h1><p>作者生成的 S0.4 语料库公开位于 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>，包含 Reference Reader、可执行 Profile、Fixture、产品证据断言、外部运行记录、标准结果、汇总、日志和 SHA-256 Manifest。WP-13 案例的边界与映射元数据位于 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/cases/wp13-multi-agent-fact-check" target="_blank" rel="noreferrer"><code>research/cases/wp13-multi-agent-fact-check</code></a>，完整 V3 证据包位于本站 <code>/evidence/tmpa/i0.5/</code>。不再存在单独的 <code>tmpa-conformance.zip</code>；Git History 即版本历史。</p><h1 id="数据可用性" tabindex="-1">数据可用性 <a class="header-anchor" href="#数据可用性" aria-label="Permalink to &quot;数据可用性&quot;">​</a></h1><p>公开演示暴露选定治理视图。私有业务数据、凭证与敏感运行记录不公开。语料库使用选定测试路径、Hash Inventory 与紧凑 Fixture，而不是导出私有生产数据。WP-13 包只包含本案例所需的任务、报告、运行节选、Git 补丁与 QA 结果；原始私有仓库不随包发布。</p><h1 id="利益冲突与来源" tabindex="-1">利益冲突与来源 <a class="header-anchor" href="#利益冲突与来源" aria-label="Permalink to &quot;利益冲突与来源&quot;">​</a></h1><p>作者是 TMPA、FCoP、CodeFlowMu 的发起者或主要开发者，并参与小典 AI 谱系。全部基线结果均由作者产生，因此更需要锁定版本、保留失败并进行独立复现。</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] FCoP Project. “FCoP — File-based Coordination Protocol,” repository README and architecture stack. GitHub, 2026. <code>https://github.com/joinwell52-AI/FCoP</code>.</p><p>[2] FCoP Project. “FCoP Runtime Specification · Single-Page Complete Edition,” 1.2.x specification line, 2026.</p><p>[3] FCoP Project. “FCoP IPC Envelope” and related machine-readable JSON Schemas, <code>spec/schemas/</code>, 2026.</p><p>[4] Python Package Index. <code>fcop</code> and <code>fcop-mcp</code> distributions, 2026.</p><p>[5] Official MCP Registry. <code>io.github.joinwell52-AI/fcop</code>, <code>fcop-mcp</code> server entry, 2026.</p><p>[6] FCoP Project. “ADR-0031: Governance Alert Layer (GAL).” Accepted 2026-05-11.</p><p>[7] FCoP Project. “ADR-0032: <code>fcop_audit()</code> — Protocol-to-Inspection Compiler.” Accepted 2026-05-12.</p><p>[8] CodeFlowMu. “TMPA Browser” public demonstration. <code>https://demo.chedian.cc/</code>. Snapshot observed 2026-07-29.</p><p>[9] TMPA Project. “TMPA Core S0.4 C01–C14 Conformance Corpus.” Corpus ID <code>tmpa-s0.4-fcop-codeflowmu-20260803</code>, executed 2026-08-03. <code>research/conformance/tmpa-core-s0.4/</code>.</p><p>[10] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3.” Author-produced evidence snapshot, observed 2026-08-05. <code>research/cases/wp13-multi-agent-fact-check/</code>.</p><h1 id="附录-a-fcop-端到端工件示例" tabindex="-1">附录 A：FCoP 端到端工件示例 <a class="header-anchor" href="#附录-a-fcop-端到端工件示例" aria-label="Permalink to &quot;附录 A：FCoP 端到端工件示例&quot;">​</a></h1><p>PM 创建 TASK，DEV Claim 并执行，随后提交独立 DEV REPORT，再由 QA 发布独立 REVIEW。当技术验证通过但生产激活会改变授权边界时，QA 可以返回 <code>needs_human</code>。</p><p>Reader 重建：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PM 创建 TASK</span></span>
<span class="line"><span>  ├─ DEV Claim 并执行</span></span>
<span class="line"><span>  ├─ DEV 提交 REPORT</span></span>
<span class="line"><span>  ├─ QA 发布 REVIEW：needs_human</span></span>
<span class="line"><span>  ├─ judgment: undetermined</span></span>
<span class="line"><span>  ├─ view: pending_human</span></span>
<span class="line"><span>  ├─ 授权人工批准或拒绝证据</span></span>
<span class="line"><span>  └─ 最终判断：valid 或 invalid</span></span></code></pre></div><p><code>needs_human</code> 节点保持在图中并可查询。依赖它的下游对象保持 <code>undetermined</code>，直至授权决定对象解决状态。权威记录是来源集合与迁移，不是渲染视图；重新排列输入文件不得改变重建图或问题集合。</p><h2 id="i0-5-理论—实现对齐" tabindex="-1">I0.5 理论—实现对齐 <a class="header-anchor" href="#i0-5-理论—实现对齐" aria-label="Permalink to &quot;I0.5 理论—实现对齐&quot;">​</a></h2><p>FCoP 作为 TMPA 概念的协议实现接受评估；CodeFlowMu 作为结合协议角色、Skill、工具、Runtime 执行、恢复与界面的工程系统接受评估。本报告区分概率型 Agent 执行证据与确定性验证机制，也区分 demonstrated 行为与完整 Core Conformance。</p>`,115))])}const A=d(c,[["render",s]]);export{C as __pageData,A as default};
